<?php
require_once __DIR__.'/../includes/init.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);if(delete_post_by_id($id))flash('success','Post deleted.');else flash('danger','Post not found.');redirect('admin/posts.php');}
$stmt=db()->query("SELECT p.*,u.name author_name,(SELECT COUNT(*) FROM comments c WHERE c.post_id=p.id) comment_count FROM posts p JOIN users u ON u.id=p.user_id ORDER BY p.created_at DESC");$posts=$stmt->fetchAll();$pageTitle='Admin Posts - Campus Connect';include __DIR__.'/_admin_header.php';
?>
<div class="admin-title"><div><h1>Posts</h1><p>Review and remove learning requests.</p></div></div><section class="admin-panel table-wrap"><table class="admin-table"><thead><tr><th>Post</th><th>Author</th><th>Comments</th><th>Date</th><th>Action</th></tr></thead><tbody><?php foreach($posts as $post): ?><tr><td><a href="<?= url('post-details.php?id='.(int)$post['id']) ?>"><strong><?= e($post['title']) ?></strong><small><?= e(excerpt($post['description'],70)) ?></small></a></td><td><?= e($post['author_name']) ?></td><td><?= (int)$post['comment_count'] ?></td><td><?= e(date('M d, Y',strtotime($post['created_at']))) ?></td><td><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$post['id'] ?>"><button class="danger" data-confirm="Delete this post and its comments?">Delete</button></form></td></tr><?php endforeach; ?></tbody></table><?php if(!$posts): ?><div class="admin-empty">No posts found.</div><?php endif; ?></section>
<?php include __DIR__.'/_admin_footer.php'; ?>
